import React, { useState } from 'react';
import { IoSearchOutline, IoChevronDownOutline } from 'react-icons/io5';
import { useNavigate } from 'react-router-dom';

export const Header = () => {
    const [searchTerm, setSearchTerm] = useState("");
    const navigate = useNavigate();

    const handleSearch = (e) => {
        if (e.key === 'Enter' || e.type === 'click') {
            if (searchTerm.trim()) {
                navigate(`/explore?q=${encodeURIComponent(searchTerm.trim())}`);
            }
        }
    };

    return (
        <section id="hero-section">
            <div className="hero-content">
                <div className="hero-badge">Explore the World</div>
                <h1>Embark on a new journey</h1>
                <p className="hero-subtitle">
                    Discover hand-picked destinations and travel insights curated for the modern adventurer.
                </p>

                <div className="search-container">
                    <IoSearchOutline className="search-icon" />
                    <input
                        type="text"
                        placeholder="Where do you want to go?"
                        className="hero-search"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        onKeyDown={handleSearch}
                    />
                    <button className="search-btn" onClick={handleSearch}>Plan Trip</button>
                </div>
                ...

                <div className="hero-stats">
                    <div className="stat-item">
                        <span className="stat-num">7+</span>
                        <span className="stat-label">Hotspots</span>
                    </div>
                    <div className="stat-sep"></div>
                    <div className="stat-item">
                        <span className="stat-num">5</span>
                        <span className="stat-label">Categories</span>
                    </div>
                    <div className="stat-sep"></div>
                    <div className="stat-item">
                        <span className="stat-num">24/7</span>
                        <span className="stat-label">Adventure</span>
                    </div>
                </div>
            </div>

            <div className="scroll-cta" onClick={() => window.scrollTo({ top: window.innerHeight, behavior: 'smooth' })}>
                <span>Explore More</span>
                <IoChevronDownOutline />
            </div>
        </section>
    );
};